"""Model-facing schema for {{name}}."""

RUN_SCHEMA = {
    "name": "{{name}}.run",
    "description": "{{summary}} Accepts one request string and returns a JSON object.",
    "parameters": {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "request": {
                "type": "string",
                "description": "The request to handle, 1 to 2000 characters.",
                "minLength": 1,
                "maxLength": 2000,
            }
        },
        "required": ["request"],
    },
}

"""Handler for {{name}}."""

import json

PLUGIN_NAME = "{{name}}"
PLUGIN_PURPOSE = "{{summary}}"
MAX_REQUEST_LENGTH = 2000


def _validated_request(args):
    """Return the trusted request string or raise ValueError."""
    if not isinstance(args, dict):
        raise ValueError("arguments must be an object")
    value = args.get("request")
    if not isinstance(value, str):
        raise ValueError("request must be a string")
    value = value.strip()
    if not value:
        raise ValueError("request must not be empty")
    if len(value) > MAX_REQUEST_LENGTH:
        raise ValueError("request must be at most 2000 characters")
    return value


def run(args, **kwargs):
    """Return a JSON string for both success and expected failure."""
    del kwargs
    try:
        request = _validated_request(args)
    except ValueError as error:
        return json.dumps({"error": str(error)}, ensure_ascii=False)
    return json.dumps(
        {
            "plugin": PLUGIN_NAME,
            "purpose": PLUGIN_PURPOSE,
            "request": request,
            "status": "received",
        },
        ensure_ascii=False,
    )
